// ---------- Display helpers ----------
export function heartCaseLabel(id) {
  return `Research Case #${String(id).padStart(3, '0')}`;
}

/** Format one raw feature value using its definition. */
export function formatHeartValue(def, value) {
  if (value === null || value === undefined) return 'Not recorded';
  if (def.values) return def.values[value] ?? String(value);
  if (def.unit) return `${value} ${def.unit}`;
  return String(value);
}

/** Look up a feature definition by id. */
export function heartFeature(id) {
  return HEART_FEATURE_DEFS.find((d) => d.id === id);
}
